import ssl,socket,urllib.request,urllib.error,json,concurrent.futures,time
sites=['https://api.telegram.org/','https://my.telegram.org/','https://www.cloudflare.com/cdn-cgi/trace','https://workers.cloudflare.com/','https://api.github.com/','https://google.com/']
def p(u):
 t=time.monotonic()
 try:
  op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
  with op.open(urllib.request.Request(u,headers={'User-Agent':'Neur0StoreTransportProbe/1.0'}),timeout=4) as r: return {'host':r.url.split('/')[2],'http':r.status,'ms':int((time.monotonic()-t)*1000)}
 except urllib.error.HTTPError as e:return {'host':u.split('/')[2],'http':e.code,'ms':int((time.monotonic()-t)*1000)}
 except Exception as e:return {'host':u.split('/')[2],'error':type(e).__name__}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex: print(json.dumps(list(ex.map(p,sites)),ensure_ascii=True))
